const $=s=>document.querySelector(s),app=$('#app');
const names={commercial_invoice:'상업송장',packing_list:'포장명세서',bill_of_lading:'선하증권',ledger:'장부'};
const english={commercial_invoice:'Commercial Invoice',packing_list:'Packing List',bill_of_lading:'Bill of Lading'};
const fields={invoice_number:'송장 번호',bill_of_lading_number:'B/L 번호',packing_list_number:'포장명세서 번호',purchase_order_number:'주문 번호',total_amount:'송장 총액',amount:'장부 금액',currency:'통화',seller:'판매자',buyer:'구매자',exporter:'수출자',shipper:'송하인',consignee:'수하인',notify_party:'통지처',description:'품명',product_code:'제품 코드',quantity:'상품 수량',unit:'수량 단위',unit_price:'단가',subtotal:'공급가액',tax:'세금',gross_weight:'총중량',net_weight:'순중량',weight_unit:'중량 단위',gross_weight_unit:'총중량 단위',net_weight_unit:'순중량 단위',total_packages:'전체 포장 개수',package_count:'포장 개수',package_type:'포장 종류',issue_date:'발행일',invoice_date:'송장 발행일',shipment_date:'선적일',departure_date:'출항일',on_board_date:'본선 적재일',transaction_date:'거래일',posting_date:'기장일',counterparty:'거래처',country_of_origin:'원산지',country_of_destination:'목적국',port_of_loading:'선적항',port_of_discharge:'양하항',place_of_delivery:'인도 장소',vessel:'선박',voyage:'항차',hs_code:'HS 코드',volume:'부피',volume_unit:'부피 단위',payment_terms:'결제 조건',incoterms:'인도 조건',buyer_reference:'구매자 참조번호',document_reference:'문서 참조번호',booking_number:'예약 번호',carrier:'운송인',mode_of_transport:'운송 방식',freight_payable_at:'운임 지급지',shipping_origin:'출발지',routing_instructions:'운송 경로',movement_type:'운송 유형',letter_of_credit_number:'신용장 번호',letter_of_credit_date:'신용장 발행일',letter_of_credit_issuing_bank:'신용장 발행은행',insurance_policy_number:'보험증권 번호',forwarding_agent:'운송 주선인',forwarding_agent_number:'주선인 번호',delivery_party:'인도처',bill_to_party:'청구처',quotation_number:'견적 번호',issue_place:'발행지',declared_value:'신고 금액',proforma_invoice_number:'견적송장 번호'};
const labels={pass:'일치',flag:'불일치',review:'검토 필요',cannot_evaluate:'정보 부족',accepted:'추출됨',missing:'정보 없음',complete:'검토 가능',partial:'일부 확인 필요',failed:'처리 실패',cancelled:'중지됨',queued:'준비 중',running:'분석 중',awaiting_review:'추출값 확인'};
let session,view='upload',jobId=null,state=null,result=null,records=[],docs={},selectedDoc=null,group='fields',filter='',selectedField=null,pending=new Map(),timer,chatTimer,chatScope=null,draft=null,files={},ledger=null,history=[],sets=[],zoom=1,reportDirty=false;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
const logo=()=>`<span class="logo">fintra<span style="color:#71916a;font-size:20px">.</span></span>`;
const authorCredit=()=>`<span class="author-credit"><span>신민철</span><a href="mailto:min.developer.acc@gmail.com">min.developer.acc@gmail.com</a></span>`;
const pet=(cls='')=>`<span class="companion ${cls}" data-companion role="img" aria-label="뿔테안경을 쓴 Fintra 감사 도우미"><span class="pet-fallback">F</span></span>`;
const btn=(text,act,cls='primary')=>`<button class="${cls}" data-action="${act}" ${({"close-chat":"대화 닫기","close-modal":"근거 닫기","logout":"로그아웃","zoom:in":"원본 확대","zoom:out":"원본 축소"})[act]?`aria-label="${({"close-chat":"대화 닫기","close-modal":"근거 닫기","logout":"로그아웃","zoom:in":"원본 확대","zoom:out":"원본 축소"})[act]}"`:""}>${text}</button>`;
const badge=s=>`<span class="badge ${esc(s)}">${icon(s==='pass'?'check':s==='flag'?'alert-circle':s==='review'?'circle-help':'circle')}${esc(labels[s]||s)}</span>`;
const bilingual=f=>f.split('_').map(w=>({bill:'Bill',of:'of',hs:'HS',id:'ID'}[w]||w[0].toUpperCase()+w.slice(1))).join(' ')+' ('+fLabel(f)+')';
const fLabel=f=>fields[f]||f.replaceAll('_',' ');
const format=(v,u='')=>{if(v===null||v===undefined||v==='')return '정보 없음';const str=String(v),m=str.match(/^([+-]?)(\d+)(\.\d+)?$/);return (m?m[1]+m[2].replace(/\B(?=(\d{3})+(?!\d))/g,',')+(m[3]||''):str)+(u?' '+u:'')};
function icons(){window.lucide?.createIcons();renderPet()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function request(path,body){const opt=body===undefined?{}:{method:'POST',headers:{'X-Fintra-Request':'1'},body:body instanceof FormData?body:JSON.stringify(body)};const r=await fetch(path,opt);let d;try{d=await r.json()}catch{throw Error('서버 응답을 확인하지 못했습니다.')};if(!r.ok)throw Error(d.error||'요청을 처리하지 못했습니다.');return d}
const api=s=>`/api/analyses/${jobId}${s}`;
function shell(content,step){document.body.dataset.view=view;app.innerHTML=`<div class="layout"><aside class="sidebar">${logo()}<div class="workspace row"><span class="initial">F</span><div>Fintra Studio<small style="display:block;margin-top:3px">감사 워크스페이스</small></div></div><nav>${btn(icon('layout-dashboard')+'새 검토','new',view==='upload'?'active':'')}${btn(icon('folder-clock')+'검토 기록','history',view==='history'?'active':'')}</nav><div class="spacer"></div><div class="note"><span class="status-dot"></span> 팀 테스트 공간</div>${authorCredit()}</aside><main class="main"><header class="topbar"><div class="breadcrumb">워크스페이스 <span style="margin:0 12px">/</span> <strong>${view==='history'?'검토 기록':view==='report'?'보고서':'거래 검토'}</strong></div><div class="row"><span class="badge">TEAM PREVIEW</span><span class="avatar">${esc(session?.name?.slice(0,1)||'F')}</span>${btn(icon('log-out'),'logout','icon-button')}</div></header><div class="content">${step?steps(step):''}${content}</div></main></div>`;icons()}
function steps(active){return `<nav class="steps" aria-label="검토 단계">${['자료 업로드','추출값 확인','거래 비교','보고서'].map((label,i)=>`<button class="step ${i+1===active?'active':''}" data-action="step:${i+1}" ${i+1===active?'aria-current="step"':''} ${i===1&&!records.length||i>1&&!result?.audit?'disabled':''}><b>${i+1<active?'✓':i+1}</b>${label}</button>`).join('')}</nav>${active>1&&view!=='progress'?btn(icon('arrow-left')+'뒤로가기','step:'+Math.max(1,active-1),'ghost step-back'):''}`}
function heading(k,title,action=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1></div>${action}</div>`}
async function init(){session=await request('/api/session');if(!session.authenticated)return login();await boot()}
function login(){$('#supporter').hidden=true;app.innerHTML=`<div class="login"><section class="login-art">${logo()}<div class="eyebrow" style="margin-top:60px">YOUR INTELLIGENT AUDIT PARTNER</div><h1>복잡한 거래도,<br><em>명확하게.</em></h1>${pet()}<footer>${authorCredit()}</footer></section><section class="login-form"><form id="loginForm"><div class="eyebrow">Your review starts here</div><h2>${session.setup?'워크스페이스 시작하기':'다시 만나 반갑습니다'}</h2><label>이름<input name="name" autocomplete="username" required placeholder="이름을 입력하세요"></label><label>비밀번호<input name="password" type="password" autocomplete="current-password" minlength="${session.setup?10:1}" required placeholder="${session.setup?'10자 이상':'비밀번호를 입력하세요'}"></label><button class="primary" type="submit">${session.setup?'워크스페이스 만들기':'로그인'}${icon('arrow-right')}</button><p class="login-help">${session.setup?'이 PC의 팀 테스트 계정을 만듭니다.':'이 워크스페이스의 계정으로 로그인하세요.'}</p><div id="loginError"></div></form></section></div>`;icons();$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await request('/api/login',Object.fromEntries(new FormData(e.target)));session=await request('/api/session');await boot()}catch(err){$('#loginError').innerHTML=`<div class="error">${esc(err.message)}</div>`;b.disabled=false}}}
async function boot(){app.innerHTML=`<div class="boot">${logo()}${pet()}<div class="loading-line"></div><p id="readyText" aria-live="polite">서비스 준비 중</p></div>`;const start=Date.now();for(;;){try{const s=await request('/api/readiness');if(s.ready)break;$('#readyText').textContent=s.error||'문서 분석 서비스를 준비하고 있습니다';if(Date.now()-start>180000)throw Error('서비스 연결이 지연되고 있습니다. 시작 파일을 확인하고 다시 시도하세요.')}catch(e){app.innerHTML=`<div class="boot">${logo()}<p>${esc(e.message)}</p>${btn('다시 연결','boot')}</div>`;return}await new Promise(r=>setTimeout(r,1500))}try{sets=(await request('/api/verified-sets')).sets||[]}catch{}if(location.hash.match(/^#[a-f0-9]{32}$/)){jobId=location.hash.slice(1);await poll()}else upload()}
function upload(){view='upload';clearTimeout(timer);shell(`${heading('NEW REVIEW','새로운 검토를 시작하세요')}<section class="hero"><div><div class="eyebrow">DOCUMENT INTELLIGENCE</div><h2>자료를 연결하면,<br>차이가 보입니다.</h2><p>같은 거래의 증빙을 함께 올려주세요.</p></div>${pet()}</section><div class="uploads">${Object.keys(english).map((t,i)=>`<article class="upload-card ${files[t]?'selected':''}" data-drop="${t}"><div class="row between"><div class="doc-icon">${icon(['file-text','package','ship'][i])}</div>${documentTip(t)}</div><h3>${names[t]}</h3><small>${english[t]}</small>${files[t]?`<div class="row between"><span class="filename">${esc(files[t].name)}</span>${btn(icon('x'),'remove:'+t,'icon-button')}</div>`:`<button class="select-file" data-action="file:${t}">${icon('upload')}파일 선택 또는 끌어놓기</button>`}<input type="file" data-file="${t}" accept="image/png,image/jpeg,image/webp,image/bmp"></article>`).join('')}</div><div class="ledger"><div class="row">${icon('table-2')}<div><h3>장부 CSV <span class="badge">선택사항</span></h3><p>${ledger?esc(ledger.name):'장부 없이 증빙만 비교할 수 있어요'}</p></div></div><div class="row ledger-tools">${btn(ledger?'변경':'파일 선택','file:ledger','secondary')}${documentTip('ledger')}</div><input type="file" data-file="ledger" accept=".csv" hidden></div>${ledger?`<label class="section-note" style="margin-top:16px"><input id="basis" type="checkbox"> 장부 금액이 송장의 최종 총액입니다</label>`:''}<details><summary>분석 설정</summary><div class="row"><label>문서 언어 <select id="lang"><option value="en">영어</option><option value="korean">한국어</option></select></label><label>회계기준 <select id="framework"><option value="">미지정</option><option value="K-IFRS">K-IFRS</option><option value="일반기업회계기준">일반기업회계기준</option></select></label></div></details><div class="actions"><small>${Object.keys(files).length}개 증빙 선택 · PNG, JPG, WEBP · 총 64 MB</small>${btn('문서 읽기 '+icon('arrow-right'),'start')}</div>${sets.length?`<section class="examples"><div class="row between"><h3>먼저 둘러보세요</h3><small>가상 거래 예시 · 실제 OCR 실행</small></div><div class="example-grid">${sets.slice(0,3).map((s,i)=>`<button class="example-card" data-action="example:${esc(s.set_id)}"><div><span>${esc(s.label||'예시 거래 '+(i+1))}</span><small>장부 + 송장 + 포장명세서 + 선하증권</small></div>${icon('arrow-up-right')}</button>`).join('')}</div></section>`:''}`,1);document.querySelectorAll('[data-file]').forEach(n=>n.onchange=()=>selectFile(n.dataset.file,n.files[0]));document.querySelectorAll('[data-drop]').forEach(n=>{n.ondragover=e=>{e.preventDefault();n.classList.add('drag')};n.ondragleave=()=>n.classList.remove('drag');n.ondrop=e=>{e.preventDefault();selectFile(n.dataset.drop,e.dataTransfer.files[0])}})}
function selectFile(type,file){if(!file)return;if(type==='ledger')ledger=file;else files[type]=file;upload()}
async function start(setId){$('#chat').hidden=true;document.body.classList.remove('chat-open');clearTimeout(chatTimer);let response;if(setId)response=await request('/api/verified-run',{set_id:setId});else{if(!Object.keys(files).length)throw Error('증빙 파일을 선택하세요.');const f=new FormData();for(const file of Object.values(files))f.append('documents',file);if(ledger)f.append('ledger',ledger);f.append('settings',JSON.stringify({lang:$('#lang')?.value||'en',framework:$('#framework')?.value||null,audit:{ledger_amount_basis:$('#basis')?.checked?'invoice_total':'unspecified'}}));response=await request('/api/analyses',f)}jobId=response.id;await request('/api/support/bind',{analysis_id:jobId});location.hash=jobId;docs={};pending.clear();result=null;await poll()}
async function poll(){clearTimeout(timer);try{state=await request(api(''));if(state.status==='awaiting_review'){records=state.document_records;await Promise.all(records.filter(r=>r.result_file).map(async r=>{docs[r.id]=await request(api('/documents/'+r.id))}));selectedDoc=selectedDoc&&docs[selectedDoc]?selectedDoc:Object.keys(docs)[0];return review()}if(['complete','partial'].includes(state.status)){result=await request(api('/result'));records=result.documents;const guideOpen=!$('#chat').hidden&&!!$('#supportForm'),unsent=$('#supportForm textarea')?.value||'';results();if(guideOpen){await openChat(null);$('#chatForm textarea').value=unsent}return}if(['failed','cancelled'].includes(state.status)){view='progress';shell(`${heading('ANALYSIS PAUSED',state.status==='cancelled'?'분석을 중지했습니다':'자료를 확인해 주세요')}<div class="error">${esc(state.error||'문서를 처리하지 못했습니다.')}</div><div class="actions">${btn('새 검토 시작','new')}</div>`,1);return}progress();timer=setTimeout(poll,900)}catch(e){toast(e.message);shell(`<div class="empty">${icon('wifi-off')}연결을 확인하지 못했습니다.<br><br>${btn('다시 확인','poll')}</div>`)}}
function progress(){view='progress';const reading=!state.comparison_ready&&state.stage!=='audit',elapsed=Math.floor(Date.now()/1000-(state.comparison_started||state.created));shell(`<section class="progress-view">${pet()}<div class="eyebrow">FINTRA IS WORKING</div><h2 style="margin-top:14px">${reading?'문서 속 정보를 읽고 있어요':'거래의 근거를 연결하고 있어요'}</h2><p class="muted">${esc(reading?state.current_file||'증빙 확인 중':'일치하는 값과 검토할 차이를 확인합니다')}</p><div class="progress-stages">${['문서 읽기','거래 비교','근거 정리'].map((s,i)=>`<span class="progress-stage ${i===(reading?0:state.comparison_ready?2:1)?'current':''}">${icon(i===(reading?0:state.comparison_ready?2:1)?'loader-circle':'circle-check')}${s}</span>`).join('')}</div><div class="loading-line"></div><small style="margin-top:22px">${Math.floor(elapsed/60)}분 ${elapsed%60}초</small>${btn('분석 중지','cancel','ghost')}</section>`,reading?1:3)}
function allCells(d){return [['fields',d.fields],...d.items.map((r,i)=>[String(i),r])].flatMap(([g,row])=>Object.entries(row).map(([f,c])=>({g,f,c})))}
function getCell(g,f){return g==='fields'?docs[selectedDoc].fields[f]:docs[selectedDoc].items[Number(g)][f]}
function cellId(g,f){return `${selectedDoc}:${g}:${f}`}
function review(){view='review';if(!selectedDoc){shell(`<div class="empty">문서를 읽지 못했습니다.${btn('새 검토','new')}</div>`);return}const d=docs[selectedDoc];shell(`${heading('DOCUMENT REVIEW','문서를 읽었습니다. 확인해 주세요.',`<span class="badge">${records.filter(r=>r.status==='complete').length}개 문서</span>`)}<div class="doc-tabs">${records.map(r=>`<button class="${selectedDoc===r.id?'active':''}" data-action="doc:${r.id}">${icon('file-text')}${esc(names[r.document_type]||r.name)}${r.status==='failed'?badge('failed'):''}</button>`).join('')}</div><div class="review-layout"><div id="documentViewer"></div><section class="fields-panel"><div class="row between" style="margin-bottom:15px"><div class="segmented">${btn('문서 정보','group:fields',group==='fields'?'active':'')}${btn('품목 '+d.items.length,'group:items',group==='items'?'active':'')}</div><span id="editCount" class="field-review-label">${pending.size?'수정 '+pending.size+'건':'원본을 클릭해 확인'}</span></div><div class="fields-toolbar"><input id="fieldSearch" placeholder="항목 검색" aria-label="항목 검색" value="${esc(filter)}"></div><div id="fieldList" class="field-list"></div></section></div>${state.failures?.length?`<div class="error">${state.failures.length}개 문서를 읽지 못했습니다. 새 검토에서 파일을 다시 선택하세요.</div>`:''}<div class="review-bottom"><small id="saveStatus">수정값은 OCR 원문과 별도로 기록됩니다.</small><div class="row">${btn('수정 저장','save','secondary')}${btn('확인 완료 · 비교 시작 '+icon('arrow-right'),'compare')}</div></div>`,2);renderViewer();renderFields();$('#fieldSearch').oninput=e=>{filter=e.target.value;renderFields()};if(state.status!=='awaiting_review'){document.querySelectorAll('[data-action="save"],[data-action="compare"]').forEach(n=>n.disabled=true)}}
function renderFields(){const d=docs[selectedDoc];const cells=allCells(d).filter(x=>(group==='fields'?x.g==='fields':x.g!=='fields')&&(!filter||(bilingual(x.f)+' '+(x.c.value||'')).toLowerCase().includes(filter.toLowerCase())));let last=null;$('#fieldList').innerHTML=cells.map(({g,f,c})=>{let h='';if(g!==last&&g!=='fields'){h=`<div class="field-group-title">품목 ${Number(g)+1}</div>`;last=g}const changed=pending.has(cellId(g,f));return h+`<div class="field-row ${changed?'edited':''} ${selectedField===g+':'+f?'active':''}" data-field-row="${g}:${f}"><div class="row between"><span>${esc(bilingual(f))}</span>${c.human_review?'<span class="badge">사용자 확인</span>':badge(c.status)}</div><input aria-label="${esc((g==='fields'?'':'품목 '+(Number(g)+1)+' ')+fLabel(f))}" data-edit="${g}:${f}" value="${esc(c.value??'')}" placeholder="정보 없음"><div class="row between" style="margin:5px 0 0"><span class="source">${esc(c.raw_text?'원문 · '+c.raw_text:'원문 근거 없음')}</span>${c.status==='review'?`<button class="ghost" style="font-size:10px" data-action="confirm:${g}:${f}">값 확인</button>`:''}</div></div>`}).join('')||'<div class="empty">해당 항목이 없습니다.</div>';$('#fieldList').querySelectorAll('[data-edit]').forEach(n=>{n.disabled=state.status!=='awaiting_review';n.onfocus=()=>{selectedField=n.dataset.edit;highlight()};n.oninput=()=>{const [g,f]=n.dataset.edit.split(':');getCell(g,f).value=n.value||null;pending.set(cellId(g,f),{document_id:selectedDoc,group:g,field:f,value:n.value||null});n.closest('.field-row').classList.add('edited');$('#editCount').textContent='수정 '+pending.size+'건'}});$('#fieldList').querySelectorAll('[data-action^="confirm:"]').forEach(n=>n.disabled=state.status!=='awaiting_review');icons()}
function renderViewer(target='#documentViewer',doc=docs[selectedDoc],recordId=selectedDoc,evidence=null){const pages=doc.ocr?.pages||[],page=pages[0]||{page:1,width:1,height:1},tokens=evidence||doc.ocr?.tokens||[];const r=records.find(r=>r.id===recordId);const image=r?.images?.[String(page.page)];$(target).innerHTML=`<div class="viewer"><div class="viewer-toolbar"><span>${esc(r?.name||'원본 증빙')}</span><div class="row"><span>1 / ${pages.length||1}</span>${btn(icon('minus'),'zoom:out','icon-button')}${btn(icon('plus'),'zoom:in','icon-button')}</div></div><div class="image-scroll"><div class="image-stage" style="width:${zoom*100}%">${image?`<img width="${page.width}" height="${page.height}" src="${api('/documents/'+recordId+'/image/'+page.page)}" alt="${esc(names[doc.document_type]||'증빙')} 원본">${tokens.filter(t=>(t.page||1)===page.page&&t.bbox).map((t,i)=>{const b=t.bbox;const xs=b.map(p=>p[0]),ys=b.map(p=>p[1]);return `<button class="bbox ${evidence?'active':''}" aria-label="원문 ${esc(t.selected_text||t.text||'근거')}" data-token="${esc(t.token_id||t.id||'')}" title="${esc(t.selected_text||t.text)}" style="left:${Math.min(...xs)/page.width*100}%;top:${Math.min(...ys)/page.height*100}%;width:${(Math.max(...xs)-Math.min(...xs))/page.width*100}%;height:${(Math.max(...ys)-Math.min(...ys))/page.height*100}%"></button>`}).join('')}`:'<div class="empty">원본 이미지가 함께 제공되지 않았습니다.</div>'}</div></div></div>`;watchOriginalImage($(target));$(target).querySelectorAll('[data-token]').forEach(n=>n.onclick=()=>{const hit=allCells(doc).find(x=>[...(x.c.evidence||[]),...(x.c.label_evidence||[])].some(e=>e.token_id===n.dataset.token));if(hit&&view==='review'){group=hit.g==='fields'?'fields':'items';selectedField=hit.g+':'+hit.f;review();const row=$(`[data-field-row="${selectedField}"]`);row?.scrollIntoView({block:'nearest'});highlight()}});icons()}
// Keep image loading, transfer errors and retry visible on remote connections.
function watchOriginalImage(host){
 const img=host.querySelector('.image-stage>img');if(!img)return;
 const status=document.createElement('div');status.className='original-image-status';status.setAttribute('role','status');
 const message=document.createElement('span'),retry=document.createElement('button');retry.type='button';retry.className='secondary';retry.textContent='원본 다시 불러오기';
 const link=document.createElement('a');link.href=img.src;link.target='_blank';link.rel='noopener';link.textContent='원본 별도로 열기';
 status.append(message,retry,link);host.querySelector('.viewer-toolbar').after(status);
 let timer;
 const loaded=()=>{clearTimeout(timer);status.hidden=true;};
 const failed=()=>{clearTimeout(timer);status.hidden=false;message.textContent='원본 이미지를 불러오지 못했습니다. 다시 시도하거나 로그인 상태를 확인해 주세요.';retry.hidden=false;};
 const loading=()=>{clearTimeout(timer);status.hidden=false;message.textContent='원본 이미지를 불러오고 있습니다.';retry.hidden=true;timer=setTimeout(()=>{if(!img.isConnected)return;if(img.complete&&img.naturalWidth){loaded();return;}message.textContent='원본 이미지 전송이 지연되고 있습니다.';retry.hidden=false;},15000);};
 img.onload=loaded;img.onerror=failed;
 retry.onclick=()=>{loading();const url=new URL(link.href);url.searchParams.set('retry',Date.now());img.src=url.href;};
 loading();if(img.complete){if(img.naturalWidth)loaded();else failed();}
}
function highlight(){document.querySelectorAll('.field-row').forEach(r=>r.classList.toggle('active',r.dataset.fieldRow===selectedField));const [g,f]=(selectedField||'').split(':');if(!g)return;const c=getCell(g,f),ids=new Set([...(c.evidence||[]),...(c.label_evidence||[])].map(e=>e.token_id));document.querySelectorAll('.bbox').forEach(b=>b.classList.toggle('active',ids.has(b.dataset.token)))}
async function save(silent=false){if(!pending.size){if(!silent)toast('변경된 사항이 없습니다.');return}const saved=await request(api('/corrections'),{changes:[...pending.values()]});pending.clear();for(const r of records)if(r.result_file)docs[r.id]=await request(api('/documents/'+r.id));if(!silent)toast(saved.saved?'내용이 변경되었습니다.':'변경된 사항이 없습니다.');review()}
function title(c){if(c.reason==='ledger_amount_basis_unspecified')return '장부 금액의 비교 기준';return {ledger_invoice_amount_comparison:'장부와 송장 금액',ledger_invoice_currency_comparison:'통화',ledger_invoice_counterparty_comparison:'거래처',document_presence:'필수 증빙',item_quantity_comparison:'상품 수량',item_gross_weight_comparison:'품목별 총중량',item_net_weight_comparison:'품목별 순중량',item_package_count_comparison:'품목별 포장 개수',document_gross_weight_comparison:'총중량',document_net_weight_comparison:'순중량',document_package_count_comparison:'포장 개수',invoice_transaction_date_review:'거래일과 송장 발행일',invoice_posting_date_review:'기장일과 송장 발행일',cross_document_date_review:'선적 관련 날짜',transaction_link_review:'거래 연결',unmatched_item:'품목 연결',item_table_unavailable:'품목 정보',item_unit_comparison:'수량 단위',item_product_code_comparison:'제품 코드',item_description_comparison:'품명'}[c.type]||(c.type.startsWith('reference_')?fLabel(c.type.slice(10)):c.title||'검토 항목')}
function evidenceType(e){const id=e.source?.entity_id;for(const t of result?.audit?.transactions||[])for(const [kind,doc] of Object.entries(t.documents||{}))if(doc.id===id)return kind;return e.source?.row_index!==undefined?'ledger':null}
function values(c){return (c.evidence||[]).filter(e=>!['currency','unit','weight_unit','gross_weight_unit','net_weight_unit'].includes(e.field_name)||!(c.evidence||[]).some(x=>['amount','total_amount','quantity','gross_weight','net_weight'].includes(x.field_name))).map(e=>{const kind=evidenceType(e),unit=(c.evidence||[]).find(x=>x.source?.entity_id===e.source?.entity_id&&x.field_name===(e.field_name?.includes('amount')?'currency':e.field_name?.includes('weight')?'weight_unit':'unit'))?.normalized_value||c.context?.comparison_unit||'';return {name:names[kind]||'증빙',field:fLabel(e.field_name),value:format(e.normalized_value,['amount','total_amount','quantity','gross_weight','net_weight'].includes(e.field_name)?unit:'')}})}
function explanation(c){if(c.reason==='ledger_amount_basis_unspecified')return '장부 금액이 송장 최종 총액인지 확인이 필요합니다.';if(c.reason==='different_units_or_currencies')return '단위 또는 통화가 달라 직접 비교할 수 없습니다.';if(c.reason==='upstream_mapping_or_normalization_review')return '추출값의 원본 확인이 필요합니다.';if(c.status==='cannot_evaluate'){const missing=(c.evidence||[]).filter(e=>e.normalized_value==null).map(e=>(names[evidenceType(e)]||'증빙')+'의 '+fLabel(e.field_name));return missing.length?[...new Set(missing)].join(', ')+' 값을 확인하지 못해 비교하지 않았습니다.':'필요한 값·단위 또는 비교 범위가 확인되지 않았습니다.'};if(c.status==='review')return c.type.includes('date')?'날짜의 역할과 거래 조건을 확인하세요.':'원본과 연결 관계를 확인하세요.';return ''}
function card(c){return `<article class="check-card ${c.status}"><div class="check-head"><div><h3>${esc(title(c))}</h3><div class="check-pair">${esc([...new Set(values(c).map(v=>v.name))].join(' ↔ '))}</div></div>${badge(c.status)}</div><div class="comparison-values">${values(c).map(v=>`<div class="comparison-value"><small>${esc(v.name)} · ${esc(v.field)}</small><strong>${esc(v.value)}</strong></div>`).join('')}</div><div class="check-foot"><span class="${c.values?.difference!=null?'difference':''}">${c.values?.difference!=null?'차이 '+esc(format(c.values.difference,c.context?.comparison_unit)):esc(explanation(c))}</span><button data-action="evidence:${esc(c.check_id)}">근거 보기 ${icon('arrow-up-right')}</button></div>${insightCard(c)}</article>`}
function insightCard(c){const i=result.presentation?.insights?.[c.check_id];return i?`<div class="review-insight"><strong>회계 검토 · ${esc(i.assertion)}</strong><p>${esc(i.impact)}</p><small>다음 확인</small><p>${esc(i.action)}</p></div>`:''}
function missingSummary(checks,passes){if(!checks.length)return '';const groups=new Map();for(const c of checks){const key=c.type;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(c)}return `<section class="missing-summary"><h4>${icon('circle-help')} 정보 부족으로 남은 이유</h4><p>아래 필수값을 확인하지 못했습니다. 문서 조합별 반복 검사는 위의 핵심 검토 영역으로 묶었으며, 누락을 일치로 처리하지 않았습니다.</p><ul>${[...groups.values()].map(cs=>{const missing=[...new Set(cs.flatMap(c=>(c.evidence||[]).filter(e=>e.normalized_value==null).map(e=>(names[evidenceType(e)]||'증빙')+' · '+fLabel(e.field_name))))];return `<li><div><b>${esc(title(cs[0]))}</b><small>${esc(missing.join(' / ')||explanation(cs[0]))}</small></div>${btn('원본 확인','evidence:'+cs[0].check_id,'secondary')}</li>`}).join('')}</ul><p>먼저 원본에 값이 있는지 확인하세요. 원본에 있으면 추출값을 수정하고, 원본에도 없으면 해당 정보가 기재된 추가 자료가 필요합니다. 문서 전체 합계와 품목별 값은 별개입니다. 정보 부족 자체를 회계 오류나 손실로 판정한 것은 아닙니다.</p></section>`}
function results(){view='results';const txs=result.audit?.transactions||[],sum=result.presentation?.summary||{};shell(`${heading('REVIEW OVERVIEW','거래의 차이를 확인하세요',btn(icon('file-pen-line')+'보고서 작성','report','secondary'))}<div class="stats"><div class="stat"><small>전체 거래</small><b class="number">${txs.length}</b></div><div class="stat flag"><small>검토 필요 거래</small><b class="number">${sum.review||0}</b></div><div class="stat pass"><small>비교 범위 내 일치</small><b class="number">${sum.pass||0}</b></div><div class="stat"><small>정보 부족 거래</small><b class="number">${sum.cannot_evaluate||0}</b></div></div><div class="result-grid"><div>${txs.map(t=>{const checks=t.checks||[],issues=checks.filter(c=>['flag','review'].includes(c.status)),passes=checks.filter(c=>c.status==='pass'),optional=new Set(result.presentation?.coverage?.[t.transaction_id]?.supplementary_ids||[]),unknown=checks.filter(c=>c.status==='cannot_evaluate'&&!optional.has(c.check_id)),supplementary=checks.filter(c=>optional.has(c.check_id));return `<section class="panel transaction"><div class="transaction-head"><div><div class="eyebrow">TRANSACTION</div><h3 style="margin-top:7px">${esc(t.ledger?.fields?.transaction_id?.value||t.documents?.commercial_invoice?.fields?.invoice_number?.value||t.transaction_id)}</h3></div>${btn(icon('sparkles')+'AI 검토','chat:'+t.transaction_id,'ai-action')}</div>${comparisonOverview(result.review_result?.transactions.find(r=>r.transaction_id===t.transaction_id),t)}${!result.review_result?issues.map(card).join('')+missingSummary(unknown,passes):''}${supplementary.length?`<details class="supplementary"><summary>검토 대상 아님(N/A) · 보조 필드 상세</summary><p>필수 비교값의 누락과 구분합니다. 해당 문서에 보조 참조번호나 품목별 중량 등이 없어 비교하지 않았습니다. 일치로 처리한 항목은 아닙니다.</p>${supplementary.map(card).join('')}</details>`:''}<details><summary>상세 비교 근거 · 일치 항목 펼치기</summary>${passes.map(card).join('')}</details>${unknown.length?`<details><summary>필수 누락 관련 상세 비교 근거</summary>${unknown.map(card).join('')}</details>`:''}</section>`}).join('')||'<div class="panel empty">연결된 거래가 없습니다. 참조번호와 추출값을 확인하세요.</div>'}${(result.audit?.unmatched_documents||[]).map(u=>`<div class="panel transaction"><h3>거래 연결 확인</h3><p class="section-note">${esc(names[u.document.document_type])} · 공통 참조번호를 확인하세요.</p>${badge('review')}</div>`).join('')}${result.failures?.length?`<div class="error">${result.failures.map(f=>esc(f.error)).join('<br>')}</div>`:''}</div><aside class="result-aside"><div class="ai-card"><div class="ai-orbit-icon">${icon("sparkles")}</div><h3>함께 검토할까요?</h3><p>해석부터 확인 절차, 검토 메모까지.</p>${btn(icon('sparkles')+'Fintra AI와 대화','chat:','ai-action')}</div><div class="report-cta"><div class="row">${icon('file-pen-line')}<h3>검토 보고서</h3></div><small>초안을 편집하고 PDF로 저장하세요.</small>${btn('초안 열기 '+icon('arrow-right'),'report','secondary')}</div></aside></div>`,3)}
function showModal(title,html){const m=$('#modal');m.innerHTML=`<div class="row between"><h2>${esc(title)}</h2>${btn(icon('x'),'close-modal','icon-button')}</div><div class="modal-body">${html}</div>`;if(!m.open)m.showModal();icons()}
async function evidence(id,override){
 const c=override||result.audit.transactions.flatMap(t=>t.checks).find(c=>c.check_id===id);if(!c)return;
 const groups=new Map();for(const e of c.evidence||[]){const key=e.source?.entity_id||'unlinked';if(!groups.has(key))groups.set(key,{kind:evidenceType(e),entries:[]});groups.get(key).entries.push(e)}
 const tx=result?.audit?.transactions?.find(t=>(t.checks||[]).some(x=>x.check_id===c.check_id));
 for(const [kind,d] of Object.entries(tx?.documents||{}))if(!groups.has(d.id))groups.set(d.id,{kind,entries:[]});
 const list=[...groups.entries()];showModal(title(c),'<nav class="evidence-tabs" role="tablist" aria-label="원본 문서 선택"></nav><div id="evidenceBody" role="tabpanel"></div>');
 const nav=$('.evidence-tabs');let generation=0;
 nav.innerHTML=list.map(([key,g],i)=>`<button role="tab" aria-selected="${i===0}" data-evidence-tab="${i}" aria-controls="evidenceBody" tabindex="${i===0?0:-1}">${esc(names[g.kind]||'증빙')}<small>${g.entries.length?'비교 근거':'참고 문서'}</small></button>`).join('');
 async function select(i){const version=++generation,[key,g]=list[i],body=$('#evidenceBody');nav.querySelectorAll('button').forEach((n,j)=>{n.setAttribute('aria-selected',String(i===j));n.tabIndex=i===j?0:-1});body.innerHTML=g.entries.map(e=>`<div class="evidence-value"><span>${esc(fLabel(e.field_name))}</span><strong>${esc(format(e.normalized_value))}</strong></div>`).join('')||'<p class="section-note">이 검사에는 인용되지 않은 같은 거래의 문서입니다.</p>';
 if(g.kind==='ledger'){body.innerHTML+=g.entries.map(e=>`<div class="panel ledger-source">장부 ${esc(e.source?.row_index??'')}행 · ${esc(e.source?.original_column||e.field_name)}<div>원문 · ${esc(e.source?.original_value??e.raw_value??e.normalized_value)}</div></div>`).join('');return}
 const docid=result.presentation?.entity_documents?.[key];if(!docid){body.innerHTML+='<p>연결된 원본 이미지가 없습니다.</p>';return}
 const loading=document.createElement('p');loading.className='section-note';loading.setAttribute('role','status');loading.textContent='원본 문서를 불러오고 있습니다.';body.append(loading);
 try{const d=docs[docid]||await request(api('/documents/'+docid));if(version!==generation||!body.isConnected||!$('#modal').open)return;loading.remove();docs[docid]=d;const spans=g.entries.flatMap(e=>{const direct=e.ocr_evidence||e.evidence||[];return direct.length?direct:allCells(d).find(x=>x.f===e.field_name&&String(x.c.value)===String(e.normalized_value))?.c.evidence||[]});body.insertAdjacentHTML('beforeend','<div id="evidenceViewer"></div>');renderViewer('#evidenceViewer',d,docid,spans);$('#modal .modal-body').scrollTop=0}catch(err){if(version===generation&&body.isConnected){loading.remove();body.insertAdjacentHTML('beforeend',`<p class="error">${esc(err.message)}</p>`);const retry=document.createElement('button');retry.className='secondary';retry.textContent='원본 다시 불러오기';retry.onclick=()=>select(i);body.append(retry);}}
 }
 nav.querySelectorAll('button').forEach((n,i)=>{n.onclick=()=>select(i);n.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;nav.querySelectorAll('button')[j].focus();select(j)}});if(list.length)await select(0);icons();
}
async function showHistory(){$('#chat').hidden=true;document.body.classList.remove('chat-open');clearTimeout(chatTimer);clearTimeout(timer);view='history';history=await request('/api/analyses');shell(`${heading('YOUR WORKSPACE','검토 기록',btn(icon('plus')+'새 검토','new'))}<section class="panel">${history.map(h=>`<div class="history-row" data-action="open:${h.id}" role="button" tabindex="0"><div><h3>거래 검토</h3><small>${new Date(h.created*1000).toLocaleString('ko-KR')}</small></div><span class="date">${h.finished?'처리 완료':'진행 기록'}</span>${badge(h.status)}${icon('arrow-up-right')}</div>`).join('')||'<div class="empty">아직 검토한 자료가 없습니다.</div>'}</section>`)}
async function report(){view='report';if(!reportDirty){draft=await request(api('/draft'));reportDirty=false;}renderReport();const task=await request(api('/workpaper'));if(task.status==='running'){reportBusy(true);await pollWorkpaper()}else if(!draft.generation&&draft.revision===0)await generateWorkpaper()}
function reportBusy(busy){const status=$('#reportProgress');if(status){if(busy&&!status.open){status.showModal();status.focus();}else if(!busy&&status.open)status.close();}const title=$('#reportStateTitle'),hint=$('#reportStateHint');if(title)title.textContent=busy?'AI 초안 작성 중':(draft.reviewed?'검토 완료':'편집 가능한 초안');if(hint)hint.textContent=busy?'작성 완료 후 편집·저장이 열립니다.':'본문을 클릭해 수정하세요.';const paper=$('.paper');if(paper)paper.setAttribute('aria-busy',String(busy));document.querySelectorAll('.paper input,.paper textarea,#reviewed,#reportFramework,[data-action="save-report"],[data-action="pdf"],[data-action="generate-workpaper"]').forEach(n=>{n.disabled=busy;n.dataset.reportBusy=busy?'1':''})}
async function generateWorkpaper(){if(reportDirty)await saveReport();const framework=$('#reportFramework')?.value||null;reportBusy(true);try{await request(api('/workpaper'),{revision:draft.revision,framework});await pollWorkpaper()}catch(e){reportBusy(false);throw e}}
async function pollWorkpaper(){const id=jobId;const task=await request(api('/workpaper'));if(view!=='report'||id!==jobId)return;if(task.status==='running'){const n=$('#reportSave');if(n)n.textContent=task.message+(task.total?' · '+task.completed+'/'+task.total:'');const progress=$('#reportProgressText');if(progress)progress.textContent=task.message||'근거와 회계기준을 검토하고 있어요';const b=$('[data-action="generate-workpaper"]');if(b)b.disabled=true;setTimeout(()=>{if(view==='report'&&jobId===id)pollWorkpaper().catch(e=>{reportBusy(false);toast('작성 상태를 확인하지 못했습니다. 보고서를 다시 열어주세요. '+e.message)})},1500);return}if(task.status==='failed'){reportBusy(false);const n=$('#reportSave');if(n)n.textContent='AI 초안 작성 실패 · 다시 작성할 수 있습니다';toast(task.error);const b=$('[data-action="generate-workpaper"]');if(b)b.disabled=false;return}if(task.status==='complete'){reportBusy(false);draft=await request(api('/draft'));reportDirty=false;renderReport();toast(draft.generation?.status==='partial'?'일부 항목은 추가 검토가 필요합니다':'AI 조서 초안이 작성됐습니다')}}
const reviewLabels={PASS:'일치',FAIL:'불일치',MISSING:'필수정보 누락',REVIEW:'판단 필요',NOT_APPLICABLE:'검토 대상 아님'};
function comparisonOverview(review,transaction){
 if(!review)return '';
 const priority={FAIL:0,MISSING:1,REVIEW:2,PASS:3,NOT_APPLICABLE:4};
 const checks=new Map((transaction.checks||[]).map(c=>[c.check_id,c]));
 const rules=new Map((review.rule_results||[]).map(r=>[r.check_id,r]));
 const docName=v=>names[v.document_type]||names[evidenceType({source:v.source})]||'증빙';
 const sameCell=(a,b)=>a.entity_id===b.entity_id&&a.source?.item_index===b.source?.item_index;
 const sorted=rows=>[...rows].sort((a,b)=>(priority[a.status]??2)-(priority[b.status]??2));
 function groupView(g){
  const ids=g.check_ids.filter(id=>rules.get(id)?.status!=='NOT_APPLICABLE');
  const cs=ids.map(id=>checks.get(id)).filter(Boolean);
  const sourceValues=ids.every(id=>rules.get(id)?.values)?ids.flatMap(id=>rules.get(id).values):g.values||[];
  const unique=new Map();for(const v of sourceValues)unique.set(JSON.stringify([v.entity_id,v.field,v.source?.json_pointer,v.source?.item_index,v.value]),v);
  const all=[...unique.values()];
  const unitFields={amount:['currency'],total_amount:['currency'],quantity:['unit'],gross_weight:['gross_weight_unit','weight_unit'],net_weight:['net_weight_unit','weight_unit'],total_packages:['package_type'],package_count:['package_type']};
  const visible=all.filter(v=>!all.some(x=>sameCell(x,v)&&(unitFields[x.field]||[]).includes(v.field))).sort((a,b)=>(a.source?.item_index??-1)-(b.source?.item_index??-1)||(['ledger','commercial_invoice','packing_list','bill_of_lading'].indexOf(a.document_type)-['ledger','commercial_invoice','packing_list','bill_of_lading'].indexOf(b.document_type)));
  const cells=visible.map(v=>{
   const keys=unitFields[v.field]||[];let unit='';for(const k of keys){const u=all.find(x=>sameCell(x,v)&&x.field===k);if(u?.value!=null){unit=String(u.value);break}}
   if(!unit&&keys.length){const units=[...new Set(cs.filter(c=>(c.evidence||[]).some(e=>e.source?.entity_id===v.entity_id&&e.source?.json_pointer===v.source?.json_pointer)).map(c=>c.context?.comparison_unit).filter(Boolean))];if(units.length===1)unit=units[0]}
   const item=v.source?.item_index;
   return `<div class="comparison-cell ${v.value==null?'is-missing':''}"><small>${esc(docName(v))} · ${esc(fLabel(v.field))}</small><strong>${esc(format(v.value,unit))}</strong></div>`;
  });
  const rowGroups=new Map();visible.forEach((v,i)=>{const key=v.source?.item_index??'header';if(!rowGroups.has(key))rowGroups.set(key,[]);rowGroups.get(key).push(cells[i])});
  const rows=[...rowGroups].map(([key,items])=>`<div class="comparison-value-row">${key!=='header'?`<div class="comparison-item-label">품목 ${esc(Number(key)+1)}</div>`:''}<div class="comparison-cell-grid" style="--comparison-columns:${Math.min(items.length,3)}">${items.join('')}</div></div>`).join('');
  const diffs=[...new Set(cs.filter(c=>c.values?.difference!=null&&Number(c.values.difference)!==0).map(c=>{const item=c.evidence?.find(e=>e.source?.item_index!=null)?.source?.item_index;return (item!=null?'품목 '+(Number(item)+1)+' · ':'')+[...new Set(values(c).map(v=>v.name))].join(' ↔ ')+' · 차이 '+format(c.values.difference,c.context?.comparison_unit||'')}))];
  const missing=visible.filter(v=>v.value==null).map(v=>docName(v)+(v.source?.item_index!=null?' 품목 '+(Number(v.source.item_index)+1):'')+'의 '+fLabel(v.field));
  const presence=cs.filter(c=>c.type==='document_presence').map(c=>`<div class="comparison-cell"><small>${esc(names[c.context?.document_type]||'증빙')}</small><strong>${c.status==='pass'?'문서 확인됨':'문서 확인 필요'}</strong></div>`).join('');
  return `<article class="comparison-group ${g.status.toLowerCase()}"><header><h4>${esc(cs[0]?.type==='document_presence'?'증빙 확인':g.title.replace(/commercial_invoice|packing_list|bill_of_lading|shipment_date|departure_date|on_board_date/g,k=>names[k]||fields[k]))}</h4><span class="badge ${g.status==='PASS'?'pass':g.status==='FAIL'?'flag':'review'}">${esc(reviewLabels[g.status])}</span></header>${rows||`<div class="comparison-cell-grid">${presence||'<p class="section-note">이 항목에는 비교할 추출값이 없습니다.</p>'}</div>`}${missing.length?`<p class="comparison-missing">${esc([...new Set(missing)].join(', '))} 값이 없습니다. 원본에서 값을 확인해 주세요.</p>`:''}${diffs.length?`<div class="comparison-differences">${diffs.map(d=>`<span>${esc(d)}</span>`).join('')}</div>`:''}<div class="comparison-sources">${cs.length?btn(icon('scan-line')+'원본 근거 보기','group-evidence:'+encodeURIComponent(ids.join('|')),'ghost'):''}</div></article>`;
 }
 return `<section class="comparison-overview"><div class="comparison-summary"><strong>${esc(reviewLabels[review.overall_status])}</strong><span>검토 영역 ${review.review_areas.length}개 · 필수 누락값 ${review.missing_required.length}건</span></div>${sorted(review.review_areas).map(a=>`<details class="comparison-area" ${a.status!=='PASS'?'open':''}><summary><b>${esc(a.title)}</b><span class="badge ${a.status==='PASS'?'pass':a.status==='FAIL'?'flag':'review'}">${esc(reviewLabels[a.status])}</span></summary>${sorted(a.groups.filter(g=>g.status!=='NOT_APPLICABLE')).map(groupView).join('')||'<p>세부 근거를 확인해 주세요.</p>'}</details>`).join('')}<p class="section-note">일치한 영역을 펼치면 문서별 값을 확인할 수 있습니다. 보조 필드는 정상·누락 집계에서 제외합니다.</p></section>`;
}
function reviewAreas(t){if(!t)return '';const transaction=result?.audit?.transactions?.find(x=>x.transaction_id===t.transaction_id);return comparisonOverview(t,transaction||{checks:[]})}
async function groupEvidence(encoded){
 const ids=new Set(decodeURIComponent(encoded).split('|'));
 const checks=(result?.audit?.transactions||[]).flatMap(t=>t.checks||[]).filter(c=>ids.has(c.check_id));
 if(!checks.length)return;
 const entries=new Map();for(const c of checks)for(const e of c.evidence||[])entries.set(JSON.stringify([e.source?.entity_id,e.source?.json_pointer,e.source?.item_index,e.field_name,e.normalized_value]),e);
 return evidence(null,{...checks[0],evidence:[...entries.values()]});
}
function reportFacts(){const f=draft.facts;if(!f)return '';return `<section class="report-facts"><div class="eyebrow">REVIEW AREAS</div><h2>핵심 검토 결과와 근거</h2>${(f.review_result?.transactions||[]).map(reviewAreas).join('')}${f.transactions.map(t=>`<details><summary>${esc(t.title)} · 상세 검증 내역 펼치기</summary>${t.checks.map(c=>`<div class="report-fact"><b>${esc(c.title)} · ${esc(reviewLabels[c.review_status]||c.status)}</b>${c.values.map(v=>`<div class="row between"><small>${esc(v.label)}</small><span>${esc(v.value)}</span></div>`).join('')}${c.difference!=null?`<p>차이 ${esc(c.difference)} ${esc(c.unit)}</p>`:''}${btn('원본 근거','evidence:'+c.id,'ghost')}</div>`).join('')}</details>`).join('')}<h3>관련 회계기준</h3><p>직접 연결된 회계기준 없음 — 증빙 대조는 회계 인식·측정 요건의 검증과 구분합니다.</p>${(f.references||[]).length?`<h3>후속 검토용 조건부 참고 기준</h3>${f.references.map(r=>`<details><summary>${esc(r.title)}</summary><div class="report-fact"><p>${esc(r.link_reason||'추가 검토를 위한 참고 원문입니다.')}</p><p>${esc(r.excerpt||r.quote)}</p><small>${esc(r.framework)} · ${esc(r.source_type)}<br>${esc(r.source.file)}</small></div></details>`).join('')}`:''}<small>본문 편집으로 검사 판정은 변경되지 않습니다.</small></section>`}

function renderReport(){shell(`${heading('REVIEW REPORT','검토를 보고서로 완성하세요',btn(icon('arrow-left')+'비교 결과','results','secondary'))}<dialog id="reportProgress" class="report-progress" aria-labelledby="reportProgressTitle" tabindex="-1"><div class="report-progress-card" role="status" aria-live="polite"><span class="report-spinner" aria-hidden="true"></span><div><strong id="reportProgressTitle">AI가 검토보고서 초안을 작성하고 있어요</strong><p id="reportProgressText">근거와 회계기준을 검토하고 있어요</p><small>완료되면 편집과 저장이 가능해요.</small></div></div></dialog><div class="report-layout"><aside class="report-sidebar"><div class="panel" style="padding:20px"><div class="eyebrow">REPORT STATUS</div><h3 id="reportStateTitle" style="margin:14px 0">${draft.reviewed?'검토 완료':'편집 가능한 초안'}</h3><p id="reportStateHint">본문을 클릭해 수정하세요.</p><div class="rule"></div><label>적용 회계기준<select id="reportFramework" aria-label="보고서 적용 회계기준">${['','K-IFRS','일반기업회계기준'].map(v=>`<option value="${v}" ${v===(draft.generation?.framework||state?.settings?.framework||'')?'selected':''}>${v||'미지정 · 적용 확인 필요'}</option>`).join('')}</select></label><label style="font-size:12px"><input type="checkbox" id="reviewed" ${draft.reviewed?'checked':''}> 검토를 완료했습니다</label></div>${btn(icon('sparkles')+(draft.generation?'AI 초안 다시 작성':'AI 감사조서 작성'),'generate-workpaper','ai-action')}${draft.needs_regeneration?'<p class="error">이 초안은 이전 검토 규칙으로 작성되었습니다. 편집 내용은 보존되며, 최신 기준으로 반영하려면 AI 초안 다시 작성을 선택하세요.</p>':''}${draft.generation?.status==='partial'?'<p class="section-note">일부 회계 해석을 작성하지 못했습니다. 본문의 검토 대기 항목을 확인하세요.</p>':''}${btn(icon('save')+'초안 저장','save-report','secondary')}${btn(icon('download')+'PDF 저장','pdf')}<small id="reportSave">편집 버전 ${draft.revision}</small>${btn(icon('sparkles')+'AI에게 물어보기','chat:','ai-action')}</aside><article class="paper"><div class="row between">${logo()}<span class="eyebrow">REVIEW REPORT</span></div><input class="report-title" aria-label="보고서 제목" data-draft="title" value="${esc(draft.title)}"><textarea aria-label="보고서 요약" data-draft="summary" placeholder="검토 요약을 작성하세요">${esc(draft.summary)}</textarea><div class="rule"></div>${draft.sections.map((s,i)=>`<input class="section-heading" aria-label="항목 ${i+1} 제목" data-section="${i}:heading" value="${esc(s.heading)}"><textarea aria-label="항목 ${i+1} 내용" data-section="${i}:text">${esc(s.text)}</textarea>`).join('')}<h3 style="margin-top:25px">검토 의견</h3><textarea aria-label="검토 의견" data-draft="conclusion" placeholder="추가 확인 사항과 검토 의견">${esc(draft.conclusion)}</textarea>${reportFacts()}<div class="report-footer">최종 감사 판단은 담당 검토자가 수행합니다.</div></article></div>`,4);$('#reportProgress').oncancel=e=>e.preventDefault();document.querySelectorAll('[data-draft],[data-section]').forEach(n=>{if(n.tagName==='TEXTAREA'){n.style.height='auto';n.style.height=n.scrollHeight+'px'}n.oninput=()=>{if(n.tagName==='TEXTAREA'){n.style.height='auto';n.style.height=n.scrollHeight+'px'}if(n.dataset.draft)draft[n.dataset.draft]=n.value;else{const [i,k]=n.dataset.section.split(':');draft.sections[i][k]=n.value}reportDirty=true;$('#reportSave').textContent='저장하지 않은 변경사항'}});$('#reviewed').onchange=e=>{draft.reviewed=e.target.checked;reportDirty=true}}
async function saveReport(){const {facts,...editable}=draft;draft=await request(api('/draft'),editable);reportDirty=false;$('#reportSave').textContent='저장 완료 · 버전 '+draft.revision;toast('보고서 초안을 저장했습니다.')}
async function openChat(scope){document.body.classList.add('chat-open');chatScope=scope||null;$('#chat').hidden=false;$('#chat').innerHTML=`<div class="chat-head">${pet()}<div><h3>Fintra AI</h3><small>${scope?'선택한 거래':'현재 분석'}의 근거로 답합니다</small></div><div class="spacer"></div>${btn(icon('x'),'close-chat','icon-button')}</div><div class="messages" id="messages"></div><form class="chat-compose" id="chatForm"><details class="chat-example-list" open><summary>이렇게 물어보세요 · 질문 예시</summary>${btn("어떤 순서로 검토하면 좋을까?","suggest:procedure","ghost")}${btn("담당자에게 요청할 자료와 질문을 작성해줘","suggest:documents","ghost")}${btn("이 결과로 검토 메모 초안을 써줘","suggest:draft","ghost")}${btn("관련 회계 원칙을 쉽게 설명해줘","suggest:knowledge","ghost")}</details><textarea aria-label="AI 질문" placeholder="이 결과에 대해 물어보세요" maxlength="1500" required></textarea><div class="row between"><small>답변의 원본 근거를 함께 확인하세요.</small><button class="primary" aria-label="질문 보내기" type="submit">${icon('arrow-up')}</button></div></form>`;$('#chatForm').onsubmit=async e=>{e.preventDefault();const n=e.target.querySelector('textarea');try{const started=await request(api('/chat'),{question:n.value,transaction_id:chatScope,view:view});n.value='';watchChatStream(started.id,api('/chat/'+started.id+'/events'));await chatPoll()}catch(err){toast(err.message)}};icons();await chatPoll();if(innerWidth<=1100)$('#chat').scrollIntoView({behavior:'smooth',block:'start'})}
async function chatPoll(){clearTimeout(chatTimer);if($('#chat').hidden)return;try{const {messages}=await request(api('/chat'));const list=messages;for(const m of messages)if(['queued','running'].includes(m.status))watchChatStream(m.id,api('/chat/'+m.id+'/events'));const guide=(await request('/api/support/history')).messages.filter(m=>!m.analysis_id||m.analysis_id===jobId);const guidance=guide.map(m=>`<div class="message user">${esc(m.question)}</div><div class="message assistant"><small>작업 안내</small><br>${esc(m.answer||m.error||(m.status==='running'?'안내 답변을 준비하고 있어요…':'답변 중단'))}</div>`).join('');$('#messages').innerHTML=`<div class="pet-support-line"><b>안녕하세요, ${esc(session?.name||'사용자')}님!</b><br>무엇을 도와드릴까요?</div>`+guidance+(list.length?list.map(m=>`<div class="message user">${esc(m.question)}</div><div class="message assistant" data-stream-message="${m.id}">${['queued','running'].includes(m.status)?`<span class="pending">${esc(streamText.get(m.id)||'근거를 확인하고 있어요…')}</span>${btn('답변 중지','stop-chat:'+m.id,'ghost')}`:m.status==='complete'?esc(m.answer):esc(m.error||'답변 생성을 중지했습니다.')} ${m.assistance?.blocks?.length?btn(icon('file-pen-line')+'보고서에 추가','chat-to-report:'+m.id,'secondary chat-to-report'):''}${(m.citations||[]).map((c,i)=>`<button class="citation" data-cite="${m.id}:${i}">${icon(c.kind==='standard'?'book-open':'scan-line')}${esc(c.kind==='check'?title(c.check):c.title)}${icon('arrow-up-right')}</button>`).join('')}</div>`).join(''):`<div class="empty" style="padding:20px 10px">${pet()}<h3>안녕하세요, ${esc(session?.name||'사용자')}님!</h3><p>무엇을 도와드릴까요?</p></div>${['어떤 순서로 검토하면 좋을까?','담당자에게 어떤 자료를 요청해야 해?','이 결과로 검토 메모 초안을 써줘','관련 회계기준을 쉽게 설명해줘'].map(q=>`<button class="quick-question" data-question="${esc(q)}">${esc(q)}${icon('arrow-up-right')}</button>`).join('')}`);$('#messages').querySelectorAll('[data-question]').forEach(n=>n.onclick=()=>{$('#chatForm textarea').value=n.dataset.question;$('#chatForm textarea').focus()});$('#messages').querySelectorAll('[data-cite]').forEach(n=>n.onclick=()=>{const [mid,i]=n.dataset.cite.split(':');const c=messages.find(m=>m.id===mid).citations[Number(i)];if(c.kind==='check')evidence(null,c.check);else showModal(c.title,`${c.applicability==='conditional'?`<p class="section-note">조건부 참고 · ${esc((c.required_conditions||[]).join(' / '))}</p>`:''}<blockquote>${esc(c.quote||c.source?.text||'')}</blockquote><div class="rule"></div><p class="section-note">${esc(sourceProvenance(c))} · ${esc(c.source?.source?.file||c.source?.source_file||'')}</p><p class="section-note">${esc(c.source?.framework||'적용 회계기준 확인 필요')}</p>`)});const active=messages.some(m=>['queued','running'].includes(m.status))||guide.some(m=>m.status==='running');$('#chatForm button[type=submit]').disabled=active;$('#chat').classList.toggle('is-thinking',active);icons();if(active)chatTimer=setTimeout(chatPoll,1200);$('#messages').scrollTop=$('#messages').scrollHeight}catch(e){toast(e.message)}}
async function action(act){const [a,...parts]=act.split(':'),arg=parts.join(':');if(['history','logout','open'].includes(a)&&(reportDirty||pending.size)&&!confirm('저장하지 않은 변경사항이 있습니다. 이동할까요?'))return;if(a==='step')return goStep(Number(arg));if(a==='new')return resetUpload();if(a==='file')return $(`[data-file="${arg}"]`).click();if(a==='remove'){delete files[arg];return upload()}if(a==='start')return start();if(a==='example')return start(arg);if(a==='poll')return poll();if(a==='cancel'){await request(api('/cancel'),{});return poll()}if(a==='doc'){if(!docs[arg])throw Error('읽지 못한 문서입니다.');selectedDoc=arg;selectedField=null;return review()}if(a==='group'){group=arg;return review()}if(a==='save')return save();if(a==='confirm'){const [g,f]=parts,c=getCell(g,f);pending.set(cellId(g,f),{document_id:selectedDoc,group:g,field:f,value:c.value,confirm:true});c.status=c.value===null?'missing':'accepted';return renderFields()}if(a==='compare'){await save(true);await request(api('/compare'),{});return poll()}if(a==='zoom'){zoom=Math.max(.6,Math.min(2.5,zoom+(arg==='in'?.2:-.2)));if(view==='review')renderViewer();const ev=$('#evidenceViewer .image-stage');if(ev)ev.style.width=zoom*100+'%';return}if(a==='group-evidence')return groupEvidence(arg);if(a==='evidence')return evidence(arg);if(a==='history')return showHistory();if(a==='open'){$('#chat').hidden=true;document.body.classList.remove('chat-open');clearTimeout(chatTimer);result=null;draft=null;reportDirty=false;jobId=arg;location.hash=arg;docs={};pending.clear();return poll()}if(a==='results')return goStep(3);if(a==='report')return goStep(4);if(a==='generate-workpaper')return generateWorkpaper();if(a==='save-report')return saveReport();if(a==='pdf'){await saveReport();const link=document.createElement('a');link.href=api('/edited-report');link.download='Fintra-review.pdf';link.click();return}if(a==='pet')return openPet();if(a==='min-pet'){petMinimized=!petMinimized;renderPet();return}if(a==='suggest'){const prompts={procedure:'이 거래에서 어떤 순서로 검토하면 좋을까?',documents:'담당자에게 요청할 자료와 질문을 작성해줘',draft:'이 결과로 검토 메모 초안을 써줘',knowledge:'현재 검토 항목과 관련된 회계 원칙을 쉽게 설명해줘'};$('#chatForm textarea').value=prompts[arg];$('#chatForm textarea').focus();return}if(a==='chat-to-report'){const response=await request(api('/chat')),message=response.messages.find(m=>m.id===arg);if(!message?.assistance?.blocks?.length)throw Error('추가할 검토 메모가 없습니다.');if(reportDirty&&!confirm('작성 중인 보고서 변경사항을 저장하고 메모를 추가할까요?'))return;if(reportDirty)await saveReport();await report();draft.sections.push({heading:'AI 검토 메모 · 담당자 확인 필요',text:message.answer+'\n\n참고 근거: '+(message.citations||[]).map(c=>c.title).join(' / ')});reportDirty=true;renderReport();$('#reportSave').textContent='메모를 추가했습니다 · 저장 전';return}if(a==='chat')return openChat(arg);if(a==='close-chat'){$('#chat').hidden=true;document.body.classList.remove('chat-open');clearTimeout(chatTimer);return}if(a==='stop-chat'){await request(api('/chat/'+arg+'/cancel'),{});return chatPoll()}if(a==='close-modal')return $('#modal').close();if(a==='boot')return boot();if(a==='logout'){await request('/api/logout',{});clearTimeout(timer);clearTimeout(chatTimer);$('#chat').hidden=true;session=await request('/api/session');login()}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const act=b.dataset.action;if(act.startsWith('zoom:')){const stage=b.closest('.viewer')?.querySelector('.image-stage');if(stage){const current=parseFloat(stage.style.width)||100;stage.style.width=Math.max(60,Math.min(250,current+(act.endsWith('in')?20:-20)))+'%'}return}b.disabled=true;try{await action(act)}catch(err){toast(err.message)}finally{if(b.isConnected&&!b.dataset.reportBusy)b.disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role=button][data-action]'))e.target.click()});
window.addEventListener('beforeunload',e=>{if(pending.size||reportDirty){e.preventDefault();e.returnValue=''}});
init().catch(e=>{app.innerHTML=`<div class="boot">${logo()}<p>${esc(e.message)}</p>${btn('다시 연결','boot')}</div>`});

let petMinimized=false,supportMessages=[];
function petStatus(){
 if(['failed','cancelled'].includes(state?.status)&&view==='progress')return {title:state.status==='failed'?'처리를 완료하지 못했어요':'분석을 중지했어요',detail:'화면에서 원인을 확인하고 다시 시작해 주세요'};
 if(view==='progress')return {title:state?.stage==='audit'?'거래를 비교하고 있어요':state?.comparison_ready?'관련 기준을 확인하고 있어요':'문서를 읽고 있어요',detail:state?.comparison_ready?'근거를 모아 보고서를 준비합니다':state?.current_file||'잠시만 기다려 주세요',busy:true};
 if(view==='review')return {title:'추출값을 확인해 주세요',detail:pending.size?`수정한 ${pending.size}개 항목을 저장할 수 있어요`:`${records.filter(r=>r.status==='complete').length}개 문서 준비 완료 · 원본과 함께 확인해요`};
 if(view==='results'){
  const checks=(result?.audit?.transactions||[]).flatMap(t=>t.checks||[]),flags=checks.filter(c=>c.status==='flag'),reviews=checks.filter(c=>c.status==='review'),missing=checks.filter(c=>c.status==='cannot_evaluate'&&!Object.values(result?.presentation?.coverage||{}).some(x=>x.supplementary_ids.includes(c.check_id)));
  if(!checks.length)return {title:'거래 연결을 확인해 주세요',detail:'연결된 증빙이 없어 값을 비교하지 못했어요',done:true};
  const first=flags[0];return {title:flags.length?`${flags.length}개 불일치를 찾았어요`:'거래 비교를 마쳤어요',detail:first?title(first)+(first.values?.difference!=null?' · 차이 '+format(first.values.difference,first.context?.comparison_unit):' · 원본 근거 확인'):reviews.length?`${reviews.length}개 항목을 함께 검토해요`:missing.length?`필수 누락값 ${result.review_result?.transactions.reduce((n,t)=>n+t.missing_required.length,0)??missing.length}건을 확인해 주세요`:'확인한 값이 일치해요',done:true};
 }
 if(view==='report')return {title:'보고서 초안을 준비했어요',detail:reportDirty?'수정 내용을 저장해 주세요':'내용을 다듬고 PDF로 저장하세요'};
 return {title:'안녕하세요, '+(session?.name||'사용자')+'님!',detail:'무엇을 도와드릴까요? 자료 준비부터 검토까지 함께할게요'};
}
function renderPet(){const host=$('#supporter');if(!host||!session?.authenticated||!$('.layout')){if(host)host.hidden=true;return}host.hidden=false;const s=petStatus();host.className=petMinimized?'pet-minimized':'';host.innerHTML=`<button class="pet-bubble ${s.busy?'busy':''}" data-action="pet"><b>${esc(s.title)}</b><small>${esc(s.detail)}</small></button><button class="pet-button ${s.busy?'busy':''} ${s.done?'done':''}" aria-label="Fintra AI 서포터와 대화" data-action="pet">${pet()}</button><button class="pet-hide" aria-label="서포터 안내 ${petMinimized?'펼치기':'접기'}" data-action="min-pet">${petMinimized?'+':'−'}</button>`}
async function openPet(){
 const saved=(await request('/api/support/history')).messages.filter(m=>!m.analysis_id||m.analysis_id===jobId);supportMessages=saved.flatMap(m=>[{role:'user',text:m.question},{role:'assistant',text:m.answer||m.error||'답변이 중단되었습니다.',citations:m.citations||[]}]);
 if(jobId&&result?.audit&&!['review','upload','progress'].includes(view))return openChat(null);
 document.body.classList.add('chat-open');$('#chat').classList.remove('is-thinking');$('#chat').hidden=false;
 $('#chat').innerHTML=`<div class="chat-head">${pet()}<div><h3>Fintra AI</h3><small>지금 진행하는 작업을 도와드려요</small></div><div class="spacer"></div>${btn(icon('x'),'close-chat','icon-button')}</div><div class="messages" id="messages"></div><form class="chat-compose" id="supportForm"><textarea aria-label="서포터 질문" placeholder="지금 무엇을 하면 될까요?" maxlength="1500" required></textarea><div class="row between"><small>${view==='review'?'선택한 문서의 추출값과 수정할 부분을 확인해요.':'자료 준비와 Fintra 사용법을 안내해요.'}</small><button class="primary" aria-label="서포터 질문 보내기">${icon('arrow-up')}</button></div></form>`;
 function render(){const s=petStatus();$('#messages').innerHTML=`<div class="pet-support-line"><b>안녕하세요, ${esc(session?.name||'사용자')}님! 무엇을 도와드릴까요?</b></div><div class="pet-support-line"><b>${esc(s.title)}</b><br>${esc(s.detail)}</div>`+supportMessages.map(m=>`<div class="message ${m.role}">${esc(m.text)}${(m.citations||[]).filter(c=>c.kind==='standard').map(c=>`<details class="support-source"><summary>${esc(c.title)}</summary><small>${esc(sourceProvenance(c))}</small><p>${esc(c.quote)}</p><small>${esc(c.source?.source?.file||'')}</small></details>`).join('')}</div>`).join('');icons();$('#messages').scrollTop=$('#messages').scrollHeight}
 render();if(innerWidth<=1100)$('#chat').scrollIntoView({behavior:'smooth',block:'start'});$('#supportForm').onsubmit=async e=>{e.preventDefault();const n=e.target.querySelector('textarea'),button=e.target.querySelector('button'),q=n.value.trim();if(!q)return;button.disabled=true;$('#chat').classList.add('is-thinking');n.value='';supportMessages.push({role:'user',text:q});render();supportMessages.push({role:'assistant',text:'현재 작업을 확인하고 있어요…'});render();try{const started=await request('/api/support',{question:q,analysis_id:jobId,selected_document_id:selectedDoc,view:view});watchChatStream(started.id,'/api/support/'+started.id+'/events',text=>{supportMessages[supportMessages.length-1]={role:'assistant',text};if($('#supportForm'))render()});let response;for(let i=0;i<180;i++){response=await request('/api/support/'+started.id);if(response.status!=='running')break;await new Promise(r=>setTimeout(r,1000))}supportMessages[supportMessages.length-1]={role:'assistant',text:response.answer||response.error||'응답이 지연되고 있습니다. 잠시 후 다시 질문해 주세요.',citations:response.citations||[]}}catch(err){supportMessages[supportMessages.length-1]={role:'assistant',text:err.message}}finally{if($('#supportForm')){$('#chat').classList.remove('is-thinking');button.disabled=false;render()}}};
}

function coreRank(c){const t=title(c);return ['총중량','순중량','상품 수량','통화','거래처','참조번호'].findIndex(x=>t.includes(x))<0?99:['총중량','순중량','상품 수량','통화','거래처','참조번호'].findIndex(x=>t.includes(x));}

async function resetUpload(){
 if(jobId||Object.keys(files).length||ledger){const yes=await new Promise(resolve=>{const d=document.createElement('dialog');d.className='reset-confirm';d.innerHTML='<h2>자료 업로드로 이동할까요?</h2><p>자료 업로드 이동 시 현재 내용이 초기화됩니다.</p><div class="row"><button data-choice="no">아니요</button><button data-choice="yes" class="primary">예</button></div>';document.body.append(d);const done=v=>{d.close();d.remove();resolve(v)};d.querySelector('[data-choice=no]').onclick=()=>done(false);d.querySelector('[data-choice=yes]').onclick=()=>done(true);d.oncancel=e=>{e.preventDefault();done(false)};d.showModal();d.querySelector('[data-choice=no]').focus()});if(!yes)return;}
 clearTimeout(timer);clearTimeout(chatTimer);jobId=null;state=null;result=null;draft=null;reportDirty=false;records=[];docs={};files={};ledger=null;pending.clear();selectedDoc=null;selectedField=null;filter='';group='fields';location.hash='';$('#chat').hidden=true;document.body.classList.remove('chat-open');upload();
}
async function goStep(step){
 if(step===1)return resetUpload();
 if(!jobId)return;
 clearTimeout(timer);
 if(step===2){state=await request(api(''));records=state.document_records||records;await Promise.all(records.filter(r=>r.result_file&&!docs[r.id]).map(async r=>{docs[r.id]=await request(api('/documents/'+r.id))}));selectedDoc=selectedDoc&&docs[selectedDoc]?selectedDoc:Object.keys(docs)[0];review();if(state.status!=='awaiting_review'){document.querySelectorAll('[data-edit],[data-action="save"],[data-action="compare"],[data-action^="confirm:"]').forEach(n=>n.disabled=true);$('#saveStatus').textContent='비교에 사용한 추출값입니다. 단계 이동 시 내용이 유지됩니다.'}return;}
 if(step===3){if(!result?.audit)return;if(reportDirty)await saveReport();results();return;}
 if(step===4){if(!result?.audit)return;await report();}
}

function documentTip(kind){
 const tips={
 commercial_invoice:['상업송장 · Commercial Invoice','판매자가 거래 상품과 청구 내역을 적은 문서입니다.','거래 당사자, 품목·수량·단가, 통화, 송장 총액을 확인합니다. 포장명세서의 수량 및 장부 금액과 비교할 때 세금·운임·할인 포함 범위도 확인하세요.'],
 packing_list:['포장명세서 · Packing List','화물이 어떤 품목과 포장 단위로 구성되어 있는지 기록한 문서입니다.','품목별 수량, 포장 개수, 순중량·총중량을 확인합니다. 송장 및 선하증권과 같은 단위·선적 범위로 대조하세요.'],
 bill_of_lading:['선하증권 · Bill of Lading (B/L)','해상운송에서 운송인이 화물의 수령 또는 선적을 증명하는 운송 문서입니다. 일반적으로 운송계약과 화물 인도에 관한 내용을 담습니다.','송하인·수하인, 선적항·양하항, 선적일, 화물 수량·중량과 참조번호를 확인합니다. Fintra에서는 다른 증빙과 같은 거래·화물인지 대조합니다. 선적일만으로 매출 인식일을 확정하지 않습니다.'],
 ledger:['장부 CSV · Comma-Separated Values','CSV는 표의 열을 쉼표로 구분해 저장하는 텍스트 파일 형식입니다. 엑셀 등에서 CSV로 저장할 수 있습니다.','장부는 선택사항입니다. 거래 식별자, 금액, 통화 등 서비스가 요구하는 열을 포함한 CSV를 올리세요. 장부가 없으면 증빙 간 비교는 가능하지만 장부 금액 대조는 할 수 없습니다.']};
 const t=tips[kind];if(!t)return;
 return `<span class="document-tip"><button type="button" class="doc-tip" aria-label="${esc(t[0])} 설명" aria-describedby="document-tip-${kind}">${icon('info')}</button><span class="document-tip-bubble" id="document-tip-${kind}" role="tooltip"><strong>${esc(t[0])}</strong><span>${esc(t[1])}</span><span class="document-tip-purpose">${esc(t[2])}</span></span></span>`;
}

// True server token events; polling is retained for final citations and reconnect recovery.
const streamText=new Map(),chatStreams=new Map();
function watchChatStream(id,url,onText){
 if(chatStreams.has(id))return;
 if(location.hostname.endsWith('.trycloudflare.com')){
  let cursor=0,closed=false;streamText.set(id,'');chatStreams.set(id,{close(){closed=true}});
  const poll=async()=>{if(closed)return;try{const batch=await request(url+'?after='+cursor);for(const e of batch.events){cursor=e.id;if(e.event==='token'){const text=streamText.get(id)+e.data.text;streamText.set(id,text);const node=document.querySelector('[data-stream-message="'+id+'"] .pending');if(node)node.textContent=text;if(onText)onText(text)}}if(batch.done){closed=true;chatStreams.delete(id);if($('#chatForm')&&!$('#chat').hidden)chatPoll();return}}catch(e){closed=true;chatStreams.delete(id);return}setTimeout(poll,300)};poll();return;
 }
 const source=new EventSource(url);chatStreams.set(id,source);streamText.set(id,'');
 source.addEventListener('token',event=>{const text=streamText.get(id)+JSON.parse(event.data).text;streamText.set(id,text);const node=document.querySelector('[data-stream-message="'+id+'"] .pending');if(node)node.textContent=text;if(onText)onText(text);const messages=$('#messages');if(messages)messages.scrollTop=messages.scrollHeight});
 source.addEventListener('done',()=>{source.close();chatStreams.delete(id);if($('#chatForm')&&!$('#chat').hidden)chatPoll()});
 source.onerror=()=>{if(source.readyState===EventSource.CLOSED)chatStreams.delete(id)};
}

function sourceProvenance(c){const s=c.source||{},m=s.metadata||{},names={kifrs_standard:'공식 기준서',kasb_qna:'KASB 질의회신 · 공식 기준서와 구분',internal_accounting_case:'기존 보유 참고자료'};return [names[s.source_type]||s.source_type||'참고 자료',m.authority,m.paragraph?'문단 '+m.paragraph:null,m.version].filter(Boolean).join(' · ')}
